import sys
sys.dont_write_bytecode=True
import verify as v

def run(owner):
    e=v.read(owner+'_evidence.json'); checks=e['object_checks']
    def files(end,side=None,**loc):
        return [{'file':c['saved_file'],'sha256':c['raw_sha256'],**loc} for c in checks if c['saved_file'].endswith(end) and (side is None or '_'+side in c['saved_file'])]
    def manifest(ptr='',side=None):return files('figure_data_manifest.json',side,json_pointer=ptr)
    def ref(name,start,end,side='after'):
        r=next(r for r in e['publication_reference_sources'] if r['side']==side and r['path'].endswith(name))
        return {'commit':r['commit'],'path':r['path'],'blob':r['actual_blob'],'sha256':r['raw_sha256'],'line_start':start,'line_end':end}
    if owner=='HV000107':
        a=ref('appendix.tex',137,186)
        items=[
          ('CLAIM', 'Panel A changes the PP3 title to the 130M chain, removes the magnitude-comparability warning and four endpoint codes/full means, adds four Supported labels and Appendix A.3 reference. Each N=300 remains. Panel B replaces PP3/PP5 with selected-component/matched-control and task-margin language, removes visible seed181 and preserves the accuracy-improvement exclusion. Panel C changes coupling to tracks behavioral effect and renames axes. Footer removes explicit no fit or new test wording while retaining frozen descriptive status. These are source-reported assertions, not scientific certification.',files('.pdf',page=1,region='A/B/C and footer')+manifest('/plot_data/chain_supported','after')+[a]),
          ('ENDPOINT','All four stored means remain 7.120276192878565e-08, 2.3040673691981465e-08, 4.7414371121837106e-08, 4.078872356598753e-08; before/source transport lexeme is 7.1202761928785655e-08. Main-figure removal does not delete source values. Behavior remains 0.008332191656033197; +0.00833219 becomes +0.00833. Pearson/Spearman/sign agreement remain 0.617548086733788/0.8324696941077123/0.8233333333333334; .61755/.83247/.82333 become .618/.832/.823. All 300 ordered pair identities and scatter coordinates are equal and match original JSONL fields. Appendix preserves rounded causal means, disjoint 001-300/301-600/601-900/901-1200 cohorts and seed181 behavioral/readout values. No new numerical result or correction is established.',manifest('/plot_data')+files('.pdf',page=1,region='A/B/C')+[a]),
          ('PROVENANCE','Complete 84 JSON operations reproduce P01. Schema1 becomes2; base3bd8164bdf4b4f433d85a181bcfe8f6c81b41e69 separates from coordinate-free snapshot2e65dd887ba4159d4024d85b8996306cfadec023. Three geometry source records, four support booleans and four CKA/RSM matrices are added. All 390 old extracted values are equal; 29 figure assignments become supporting. All 45 source identities and 16 output-digest references authenticate. README adds pinned listings and CKA/RSM tables, removes causal/behavior/correlation tables but their values remain in manifest/appendix; scalar geometry moves to supporting. Seven output hashes change; no unseen sibling visual claim is inferred.',manifest()+files('README.md',line_start=1,line_end=114)),
          ('RENDER','Complete original PNGs and full one-page Poppler PDF renders inspected. PNG2800x2089 becomes2800x2000; PDF504x376pt becomes504x360pt. Cards, spacing and scatter placement change. Display shortening rounds identical stored data. Recorded ReportLab4.4.9/Poppler26.07.0 becomes ReportLab5.0.1/PyMuPDF1.28.2 with400dpi. Endpoint removal and Supported labels are substantive beyond rendering.',files('.pdf',page=1,region='complete page')+files('.png',region='complete canvas')+manifest('/tools')),
          ('HISTORY','README deletes the explicit failed historical370M joint residual criterion sentence and identical-byte rebuild/environment recipe. Before bytes preserve both; after appendix206-207/223-227 retains failed criterion and non-rescue. Manifest notes retain distinct D_SUF/D_DOM/D_CORE and later130M versus prospective370M-2.8B boundaries. Selected before cfd1e5b4f43be1ae3847ce943906dfc841ed5373 is an ancestor, not direct parent of ef1806bef9e4a7f55e1f7e77f7a0f08592fb4abe. Actual parent2e65dd887ba4159d4024d85b8996306cfadec023 carries the same before PDF blob. No global adoption, motive or scientific reversal is established.',files('README.md',line_start=1,line_end=114)+manifest('/notes')+[ref('appendix.tex',206,227)])]
    elif owner=='HV000113':
        reuse=[]
        for side in ['before','after']:
            for name in ['figure_data_manifest.json','README.md']:
                a=v.W3+'transitions_0/evidence/042_'+side+'_companion_'+name
                b=v.W3+'transitions_0/evidence/106_'+side+'_companion_'+name
                assert v.raw(a)==v.raw(b)
                reuse.append({'owner_file':a,'hv000103_verified_file':b,'both_raw_sha256':v.sha(v.raw(a)),'exact_bytes_equal':True,'side':side})
        e['common_companion_reuse']={'pairs':reuse,'verified_common_review':v.W4+'publication_hv000103_independent_verification_20261014/independent_evidence_check.json','verified_common_review_sha256':v.sha(v.raw(v.W4+'publication_hv000103_independent_verification_20261014/independent_evidence_check.json')),'scope':'Reuse only common complete Figure4 interval/source interpretation for these byte-identical before/after pairs. Figure3 visual, endpoints, references and scientific boundaries independently examined. All49 source identities freshly authenticate.'}
        v.write(owner+'_evidence.json',e)
        items=[
          ('CLAIM','Panel A deletes Selected/control ranks are local identities; equal rank numbers do not imply semantic homology. This is a substantive removed qualification. Five-scale causal-role recurrence title, P3/P5,P3/P5,P2/P5,P5/P4,P3/P5 pairs, five Supported cells, common selected-restored minus coefficient-matched-control contrast and historical AppendixA.4 reference are unchanged. Manuscript117 retains scale-local identities rather than same-numbered-plane homology. Deleted caveat proves neither homology nor scientific correction. Geometry claims remain partial conservation without invariance in the retained footer.',files('.pdf',page=1,region='all panels, caveats and footer')+files('.png',region='complete canvas')+[ref('main.tex',112,130)]),
          ('ENDPOINT','All398 previous extracted entries and every previous plot field are unchanged. Both XG2/XG4 5x5 CKA matrices, all50 displayed cells at two decimals, five scale labels and plane pairs are retained. Four CKA/RSM matrices independently match exact geometry-result source JSON pointers; response-blind300 pairs per family and non-invariance qualification remain. 130M D_SUF,370M D_DOM and790M/1.4B/2.8B D_CORE stay distinct in appendix. Thirty new shared entries encode ten Figure4 point means and twenty interval endpoints, not new Figure3 endpoints; common interpretation reused only after exact before/after hash equality to verified HV000103 companions.',manifest('/plot_data')+manifest('/extracted_values')+files('.pdf',page=1,region='all50 CKA cells and footers')+[ref('appendix.tex',188,229)]),
          ('PROVENANCE','Complete40 JSON operations reproduce P01: thirty interval extracted entries, objective_intervals, pair-resampling authority/source, notes and six Figure1/3/4 output hashes. Three complete README hunks add objective-bootstrap CSV/source binding and Figure4 interval wording; Figure3 source/geometry prose remains equal. All49 source and16 output digest references freshly authenticate. CSV8423ef9d1325c007ecd31849a668131197e2214d:reports/reason_router_gen4_mamba1_iclr_pair_resampling_robustness_v1/objective_bootstrap.csv is blob956f01c764871c8d27ab34dab04195dba773432e SHA256833d3f670afe4aae5a481226c49d6fc11bf710c7e521178d3d83911da0e42cd8. Verified HV000103 common semantic interpretation is reused only for exact byte-identical manifest and README pairs; no unrelated owner audit repeated.',manifest()+files('README.md',line_start=1,line_end=127)+[ref('main.tex',117,130),ref('appendix.tex',188,229)]),
          ('RENDER','Complete PNG and PDF pairs inspected through page edges, tables,50 CKA cells and footer. Removing the homology caveat closes white space and shifts table/heatmaps upward. PNG2800x2167 becomes2800x2100; PDF504x390pt becomes504x378pt. Tool records stay ReportLab5.0.1/PyMuPDF1.28.2/400dpi. Wording deletion is substantive; content repositioning/canvas changes are rendering. CKA values/colors and the partial-not-invariant geometry caveat remain.',files('.pdf',page=1,region='complete page')+files('.png',region='complete canvas')+manifest('/tools')),
          ('HISTORY','After manuscript retains the rank-homology distinction; after appendix206/223-227 retains the failed historical370M joint residual criterion and explicitly denies retrospective rescue. No causal-role,geometry or scientific claim is certified. Selected ef1806bef9e4a7f55e1f7e77f7a0f08592fb4abe to048fb78258bbe0dac29f0dfbe0310b9023ecc672 comparison proves an ancestor relation only; immediate-predecessor/global-adoption, actors, reasons and capture chronology are not inferred. All earlier failures,HV000116 chronology and open HV001006/HV001270 debts remain.',[ref('main.tex',117,130),ref('appendix.tex',188,229)]+manifest('/notes'))]
    else: raise ValueError('Unspecified owner')
    findings=[{'id':'IV'+owner[-3:]+'-'+cat,'category':cat,'interpretation':text,'evidence':[v.locator(z) for z in locs],'scientific_certification':False} for cat,text,locs in items]
    v.finish_owner(owner,findings)

if __name__=='__main__':run(sys.argv[1])
